import { test } from 'node:test';
import assert from 'node:assert/strict';
import { obterContador, zerarContador } from './solution.mjs';

test('duas chamadas devolvem a MESMA instância', () => {
  zerarContador();
  assert.equal(obterContador(), obterContador());
});

test('o estado é compartilhado: incrementar por uma referência é visto pela outra', () => {
  zerarContador();
  const contadorA = obterContador();
  const contadorB = obterContador();
  contadorA.incrementar();
  contadorA.incrementar();
  assert.equal(contadorB.valor, 2);
});

test('zerarContador zera o valor mantendo a instância única', () => {
  zerarContador();
  const antes = obterContador();
  antes.incrementar();
  zerarContador();
  const depois = obterContador();
  assert.equal(depois.valor, 0);
  assert.equal(antes, depois);
});

test('incrementar devolve o novo valor, sem repetir o anterior', () => {
  zerarContador();
  const contador = obterContador();
  const primeiro = contador.incrementar();
  const segundo = contador.incrementar();
  assert.equal(primeiro, 1);
  assert.equal(segundo, 2);
  assert.notEqual(primeiro, segundo);
});

