// SINGLETON: uma única instância compartilhada por todo o app.
// O "banco" (estado) mora no módulo; obterContador devolve SEMPRE o mesmo objeto.

let instanciaUnica = null;

export function obterContador() {
  if (instanciaUnica === null) {
    // Criação preguiçosa: a instância nasce na primeira vez em que é pedida.
    instanciaUnica = {
      valor: 0,
      incrementar() {
        this.valor += 1;
        return this.valor;
      },
    };
  }
  return instanciaUnica;
}

export function zerarContador() {
  // Necessário para testes: sem isso, o estado do singleton vazaria entre testes.
  if (instanciaUnica !== null) {
    instanciaUnica.valor = 0;
  }
}
